--
-- Name: account_login_old(character varying, character varying, character varying); Type: FUNCTION; Schema: public; Owner: spiritking
--

CREATE FUNCTION public.account_login_old(character varying, character varying, character varying) RETURNS public.res_set
    LANGUAGE plpgsql
    AS $_$declare
ppAccountID ALIAS FOR $1;
pPassword ALIAS FOR $2;
pClientIP ALIAS FOR $3;
pAccountID varchar(20);
pcount int;
pPwd char(32) default null;
pBAuthority int2 default 0; --byauthority (0-->User, 1-->GM, 254 -->BlackList, 255-->Locked)
pGMIP varchar(15) default null;

res res_set; -- (idnum,nret)

BEGIN
pAccountID = lower(ppAccountID);
res.nRet=-1;

SELECT INTO pPwd,pBAuthority,res.pIdNum pwd,byAuthority,idnum FROM "tb_user" WHERE mid=pAccountID;
GET DIAGNOSTICS pcount = ROW_COUNT;

IF pcount =0 THEN --This Account is not exist
res.pIdNum= -1;
res.nRet = 2;
RETURN res;
END IF;

IF pPwd IS null THEN
res.nRet = 2;
RETURN res;
ELSEIF pPwd <> pPassword THEN
res.nRet = 3;
RETURN res;
END IF;

IF (pBAuthority = 255 or pBAuthority = 254) THEN   --This Account was locked
res.nRet = 5;
RETURN res;
END IF;

IF pBAuthority = 1 THEN   --gmAccount byauthority=1 checkip false
SELECT INTO pGMIP ip FROM gmip WHERE ip=pClientIP;
IF pGMIP IS NULL THEN
res.nRet = 4;
RETURN res;
END IF;
END IF;

res.nRet = 1;
RETURN res;
END;
$_$;


