CREATE FUNCTION public.save_health_time(character varying, integer, integer, integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$Declare
ppMid ALIAS FOR $1;
pLoginTime ALIAS FOR $2;
pLogoutTime ALIAS FOR $3;
pLastLogoutDate ALIAS FOR $4;
pIdNum integer;
pMid varchar(20);
integer_var integer;

BEGIN

pMid=lower(ppMid);
select into pIdNum idnum from tb_user where mid=pMid;
GET DIAGNOSTICS integer_var = ROW_COUNT;
if(integer_var = 1) then
update tb_user set logintime=pLoginTime,logouttime=pLogoutTime where mid=pMid;
return pIdNum;
end if;

return 0;
END;$_$;


