--
-- Name: set_adult(character varying, integer); Type: FUNCTION; Schema: public; Owner: spiritking
--

CREATE FUNCTION public.set_adult(character varying, integer) RETURNS character
    LANGUAGE plpgsql
    AS $_$Declare
ppMid ALIAS FOR $1;
ppIsAdult ALIAS FOR $2;
pMid varchar(20);
pIsAdult smallint;
integer_var integer;
presult character(4);

BEGIN

pMid=lower(ppMid);
select into pIsAdult isadult from tb_user where mid=pMid;
GET DIAGNOSTICS integer_var = ROW_COUNT;

if(integer_var > 0 and pIsAdult=ppIsAdult) then
presult=1;
return presult;
elseif(integer_var > 0 and pIsAdult<>ppIsAdult) then
update tb_user set isadult=ppIsAdult where mid=pMid;
presult=1;
return presult;
elseif(integer_var =0) then
presult=0;
return presult;
else
presult='0xF0';
return presult;
end if;

presult='0xF0';
return presult;

end;$_$;


ALTER FUNCTION public.set_adult(character varying, integer) OWNER TO spiritking;

--
-- Name: set_blacklist(character varying, integer); Type: FUNCTION; Schema: public; Owner: spiritking
--

CREATE FUNCTION public.set_blacklist(character varying, integer) RETURNS character
    LANGUAGE plpgsql
    AS $_$-- set byauthority=254 is blacklist

Declare
ppMid ALIAS FOR $1;
ppTime ALIAS FOR $2;
pMid varchar(20);
integer_var integer;
pByAuthority smallint;
presult character(4);
BEGIN
pMid=lower(ppMid);
select into pByAuthority byauthority from tb_user where mid=pMid;
GET DIAGNOSTICS integer_var = ROW_COUNT;

if(integer_var > 0 and ppTime > 0 and pByAuthority = 254) then
presult=1;
return presult;
elseif(integer_var > 0 and ppTime > 0 and pByAuthority <> 254) then
update tb_user set byauthority=254 where mid=pMid;
presult=1;
return presult;
elseif(integer_var > 0 and ppTime = 0 and pByAuthority <> 0) then
update tb_user set byauthority=0 where mid=pMid;
presult=1;
return presult;
elseif(integer_var > 0 and ppTime = 0 and pByAuthority = 0) then
presult=1;
return presult;
elseif(integer_var = 0) then
presult=0;
return presult;
else
presult='0xF0';
return presult;
end if;

presult='0xF0';
return presult;
end;

$_$;


ALTER FUNCTION public.set_blacklist(character varying, integer) OWNER TO spiritking;

